 static Entity Open(Database db,Transaction tr,string h,OpenMode mode){ObjectId id;Need(db.TryGetObjectId(new Handle(Convert.ToInt64(h,16)),out id)&&!id.IsErased,"TEXT_HANDLE_MISSING:"+h);var e=tr.GetObject(id,mode) as Entity;Need(e!=null,"ENTITY_REQUIRED:"+h);return e;}
