 public static object Read(Database db,string[] handles,bool referenceDetails=false){Need(handles!=null&&handles.Length>0,"TEXT_HANDLES_REQUIRED");var rows=new List<object>();using(var tr=db.TransactionManager.StartTransaction())foreach(var h in handles){ObjectId targetId;Need(db.TryGetObjectId(new Handle(Convert.ToInt64(h,16)),out targetId)&&!targetId.IsErased,"HANDLE_MISSING:"+h);var target=tr.GetObject(targetId,OpenMode.ForRead);if(target is BlockTableRecord){rows.Add(ReadBlock(tr,(BlockTableRecord)target));continue;}var e=Open(db,tr,h,OpenMode.ForRead);var b=(BlockTableRecord)tr.GetObject(e.OwnerId,OpenMode.ForRead);object data;if(e is MText){var t=(MText)e;var style=(TextStyleTableRecord)tr.GetObject(t.TextStyleId,OpenMode.ForRead);data=new{text=t.Contents,plain_text=t.Text,actual_width=t.ActualWidth,actual_height=t.ActualHeight,format=Fmt(tr,t),stable=Stable(t),font=new{style=style.Name,file=style.FileName,bigfont=style.BigFontFileName}};}else if(e is DBText)data=NativeGeometryReadV1.Geometry(e);else if(e is BlockReference){var br=(BlockReference)e;data=new{definition=H(br.BlockTableRecord),name=((BlockTableRecord)tr.GetObject(br.BlockTableRecord,OpenMode.ForRead)).Name,matrix=br.BlockTransform.ToArray()};}else data=NativeDetailsReadV2.Piece(e,0);rows.Add(new{handle=e.Handle.ToString(),type=e.GetRXClass().Name,layer=e.Layer,color=e.Color.ToString(),color_index=e.ColorIndex,linetype=e.Linetype,linetype_scale=e.LinetypeScale,bounds=Bounds(e),owner=new{handle=b.Handle.ToString(),name=b.Name,layout=b.IsLayout,external=b.IsFromExternalReference||b.IsDependent,dynamic=b.IsDynamicBlock,instances=Refs(b).Select(H).ToArray()},references=referenceDetails?References(tr,b):null,data=data});}return rows;}
