 public static object Apply(Document doc,Job job,Action mutate){Need(job.texts!=null&&job.texts.Length>0&&job.texts.Select(i=>i.handle.ToUpperInvariant()).Distinct().Count()==job.texts.Length,"UNIQUE_TEXT_TARGETS_REQUIRED");var db=doc.Database;var selected=new HashSet<string>(job.texts.Select(i=>i.handle),StringComparer.OrdinalIgnoreCase);var permitted=new HashSet<string>(selected,StringComparer.OrdinalIgnoreCase);var touched=new HashSet<string>();object before=Protect(db,job.texts);
  ObjectEventHandler changed=(sender,e)=>{if(e.DBObject is Entity&&!permitted.Contains(e.DBObject.Handle.ToString()))touched.Add(e.DBObject.Handle.ToString());};ObjectErasedEventHandler erased=(sender,e)=>{if(e.Erased&&e.DBObject is Entity)touched.Add(e.DBObject.Handle.ToString());};
  using(var tr=db.TransactionManager.StartTransaction()){var styles=(TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForRead);
   foreach(var i in job.texts){var t=Open(db,tr,i.handle,OpenMode.ForRead) as MText;Need(t!=null&&t.Layer==i.layer&&t.Contents==i.text,"MTEXT_LAYER_OR_CONTENT_CHANGED");var b=(BlockTableRecord)tr.GetObject(t.OwnerId,OpenMode.ForRead);Need(!b.IsDependent&&!b.IsFromExternalReference&&!b.IsDynamicBlock,"EXTERNAL_OR_DYNAMIC_DEFINITION_NOT_SUPPORTED");Need(i.owner!=null&&H(t.OwnerId)==i.owner.handle&&b.Name==i.owner.name,"EXACT_OWNER_REQUIRED");var refs=Refs(b);Need(i.owner.instances==null||new HashSet<string>(refs.Select(H),StringComparer.OrdinalIgnoreCase).SetEquals(i.owner.instances),"AFFECTED_BLOCK_REFERENCES_CHANGED");foreach(var id in refs){var br=(BlockReference)tr.GetObject(id,OpenMode.ForRead);Need(!br.IsDynamicBlock,"DYNAMIC_REFERENCE_NOT_SUPPORTED");permitted.Add(br.Handle.ToString());}Need(i.before!=null&&i.after!=null&&CadValueCompareV1.Json(J.Serialize(i.before),J.Serialize(Fmt(tr,t))),"TEXT_FORMAT_BEFORE_CHANGED");Need(styles.Has(i.after.style)&&i.after.height>0&&i.after.width>=0&&i.after.line_spacing_factor>=.25&&i.after.line_spacing_factor<=4&&i.after.attachment>=1&&i.after.attachment<=9&&(i.after.line_spacing_style==1||i.after.line_spacing_style==2),"INVALID_FORMAT_OR_MISSING_STYLE");if(i.contents!=null)using(var probe=new MText()){probe.Contents=i.contents;Need(probe.Text==t.Text,"PLAIN_TEXT_MUST_REMAIN_IDENTICAL");}Need(i.location==null||(i.location.Length==3&&i.location.All(v=>!Double.IsNaN(v)&&!Double.IsInfinity(v))),"FINITE_LOCATION_REQUIRED");}
   db.ObjectModified+=changed;db.ObjectAppended+=changed;db.ObjectErased+=erased;try{mutate();foreach(var i in job.texts){var t=(MText)Open(db,tr,i.handle,OpenMode.ForWrite);var loc=i.location==null?t.Location:new Point3d(i.location[0],i.location[1],i.location[2]);if(i.contents!=null)t.Contents=i.contents;t.TextStyleId=styles[i.after.style];t.TextHeight=i.after.height;t.Width=i.after.width;t.Attachment=(AttachmentPoint)i.after.attachment;t.Location=loc;t.LineSpacingStyle=(LineSpacingStyle)i.after.line_spacing_style;t.LineSpacingFactor=i.after.line_spacing_factor;t.RecordGraphicsModified(true);Need(t.Contents==(i.contents??i.text)&&t.Location.DistanceTo(loc)<1e-8&&CadValueCompareV1.Json(J.Serialize(i.after),J.Serialize(Fmt(tr,t))),"TEXT_FORMAT_WRITEBACK_FAILED");var b=(BlockTableRecord)tr.GetObject(t.OwnerId,OpenMode.ForRead);foreach(var id in Refs(b)){var br=(BlockReference)tr.GetObject(id,OpenMode.ForWrite);br.RecordGraphicsModified(true);}}Need(touched.Count==0,"UNSELECTED_ENTITY_TOUCHED:"+String.Join(",",touched));tr.Commit();Need(touched.Count==0,"UNSELECTED_ENTITY_TOUCHED_ON_COMMIT");}finally{db.ObjectModified-=changed;db.ObjectAppended-=changed;db.ObjectErased-=erased;}}
