 static object EraseProtected(Database db,EraseTarget[] targets){
  var selected=new HashSet<string>(targets.Select(t=>t.handle),StringComparer.OrdinalIgnoreCase);var rows=new List<object>();
  using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);foreach(var name in targets.Select(t=>t.block).Distinct().OrderBy(x=>x)){
   Need(bt.Has(name),"BLOCK_MISSING:"+name);var b=(BlockTableRecord)tr.GetObject(bt[name],OpenMode.ForRead);
   rows.Add(new{handle=H(b.ObjectId),name=b.Name,children=b.Cast<ObjectId>().Where(id=>!id.IsErased&&!selected.Contains(H(id))).Select(H).OrderBy(x=>x).ToArray(),references=References(tr,b)});
  }}return rows;
 }
 static void VerifyErased(Database db,EraseTarget[] targets){foreach(var t in targets){ObjectId id;Need(!db.TryGetObjectId(new Handle(Convert.ToInt64(t.handle,16)),out id)||id.IsErased,"TEXT_STILL_EXISTS:"+t.handle);}}
 static object ApplyErase(Document doc,Job job,Action mutate){
  Need(job.targets!=null&&job.targets.Length>0&&job.targets.Select(x=>x.handle.ToUpperInvariant()).Distinct().Count()==job.targets.Length,"UNIQUE_TEXT_TARGETS_REQUIRED");
  var db=doc.Database;var selected=new HashSet<string>(job.targets.Select(t=>t.handle),StringComparer.OrdinalIgnoreCase);var permitted=new HashSet<string>(selected,StringComparer.OrdinalIgnoreCase);var refs=new HashSet<ObjectId>();var touched=new HashSet<string>();string before=J.Serialize(EraseProtected(db,job.targets));
  ObjectEventHandler changed=(sender,e)=>{if(e.DBObject is Entity&&!permitted.Contains(H(e.DBObject.ObjectId)))touched.Add(H(e.DBObject.ObjectId));};
  ObjectErasedEventHandler erased=(sender,e)=>{if(e.Erased&&e.DBObject is Entity&&!selected.Contains(H(e.DBObject.ObjectId)))touched.Add(H(e.DBObject.ObjectId));};
  using(var tr=db.TransactionManager.StartTransaction()){
   foreach(var t in job.targets){var e=Open(db,tr,t.handle,OpenMode.ForRead);var b=(BlockTableRecord)tr.GetObject(e.OwnerId,OpenMode.ForRead);Need(b.Name==t.block&&!b.IsLayout&&!b.IsDependent&&!b.IsFromExternalReference&&!b.IsDynamicBlock,"EXACT_STATIC_BLOCK_REQUIRED");Need(TextValue(e)==t.text,"BLOCK_TEXT_CHANGED");foreach(var id in Refs(b)){Need(!((BlockReference)tr.GetObject(id,OpenMode.ForRead)).IsDynamicBlock,"DYNAMIC_REFERENCE_NOT_SUPPORTED");refs.Add(id);permitted.Add(H(id));}}
   db.ObjectModified+=changed;db.ObjectAppended+=changed;db.ObjectErased+=erased;
   try{mutate();foreach(var t in job.targets)Open(db,tr,t.handle,OpenMode.ForWrite).Erase();foreach(var id in refs)((BlockReference)tr.GetObject(id,OpenMode.ForWrite)).RecordGraphicsModified(true);Need(touched.Count==0,"UNSELECTED_ENTITY_TOUCHED");tr.Commit();}finally{db.ObjectModified-=changed;db.ObjectAppended-=changed;db.ObjectErased-=erased;}
  }
  VerifyErased(db,job.targets);Need(CadValueCompareV1.Json(before,J.Serialize(EraseProtected(db,job.targets))),"BLOCK_SIBLINGS_OR_REFERENCES_CHANGED");doc.Editor.Regen();
  return new{operation="erase",identity="block_handle_text",erased=job.targets.Select(t=>t.handle).ToArray(),other_children_and_references_preserved=true};
 }
